    // Favor bins with large remaining space
    if post_residual > bin_capacity / 2 {
        score -= (bin_capacity - post_residual) as f64 * 0.75;
    }

    // Penalize bins that are about to be filled
    if post_residual < item_size * 1.5 {
        score += post_residual as f64 * 0.5;
    }

    // Favor bins with smaller mean residual
    score += (mean_residual - post_residual as f64).abs() * 0.5;

    // Penalize bins with fitting bins available
