    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 15.0;
    }

    // Additional reward for using bins with a good balance between residual and capacity
    if bin_residual < bin_capacity / 2 {
        score += 2.0 * bin_residual as f64 / bin_capacity as f64;
    }

    score
}

